3	import static org.assertj.core.api.Assertions.assertThat;
4	import static org.assertj.core.api.Assertions.assertThatThrownBy;
5	
6	import com.example.starter.compliance.AbstractIntegrationTest;
7	import com.example.starter.compliance.ApiException;
8	import com.example.starter.compliance.Fixtures;
9	import com.example.starter.compliance.repo.ClearanceCertificateRow;
