16	import org.springframework.beans.factory.annotation.Autowired;
17	import org.springframework.http.HttpStatus;
18	
19	/**
20	 * 清线门禁主流程与失败分支 H2 测试：
21	 * 过敏原登记乐观版本、线路占用版本、凭证双人确认与 2 小时边界、受控量产门禁、
22	 * 备案暂停/注销拒绝、失败不消耗凭证、幂等重放/异参 409。
23	 */
24	class LineControlIntegrationTest extends AbstractIntegrationTest {
25	
26	    private static final String MILK = "ALG_MILK";
27	    private static final String EGG = "ALG_EGG";
28	    private static final String PEANUT = "ALG_PEANUT";
29	
30	    @Autowired
31	    private LineControlService lineService;
32	
33	    @Autowired
34	    private ComplianceService complianceService;
35	
36	    private long approvedFiling(String productCode, int version) {
37	        long formulaId = complianceService.submitFormula(Fixtures.formula(productCode, version,
38	                List.of(Fixtures.additive("E300", "0.2")), List.of())).body().formulaId();
39	        complianceService.reviewFormula(Fixtures.ref(formulaId));
40	        complianceService.approveFormula(Fixtures.ref(formulaId));
41	        return complianceService.fileFiling(Fixtures.file(formulaId)).body().filingId();
42	    }
43	
44	    private void registerAllergens(String requestId, String productCode, int version,
45	            List<String> allergens, int expectedVersion, long at) {
46	        FormulaAllergenRequest request = Fixtures.allergens(requestId, productCode, version,
47	                allergens, expectedVersion, at);
48	        lineService.registerFormulaAllergens(request);
49	    }
50	
51	    private RegisterLineRequest freshLine(String lineCode, String lastProduct, Integer lastVersion,
52	            long at) {
53	        return Fixtures.line(Fixtures.requestId(), lineCode, lineCode + "-线", lastProduct,
54	                lastVersion, at);
55	    }
56	
57	    private ConfirmCertificateRequest certificate(String lineCode, List<String> allergens,
58	            long clearedAt, long confirmedAt) {
59	        return Fixtures.certificate(Fixtures.requestId(), "CERT-" + System.nanoTime(), lineCode,
60	                allergens, "OP-1", "RV-1", clearedAt, confirmedAt);
61	    }
62	
63	    @Test
64	    void allergenRegistrationStartsAtOneAndOptimisticUpdateIncrements() {
65	        long t0 = 1_800_000_000_000L;
66	        String requestId = Fixtures.requestId();
67	        FormulaAllergenRequest first = Fixtures.allergens(requestId, "P-A", 1,
68	                List.of(MILK, EGG), 0, t0);
69	        ServiceResult<LineControlResults.FormulaAllerView> created =
70	                lineService.registerFormulaAllergens(first);
71	        assertThat(created.body().version()).isEqualTo(1);
72	        assertThat(created.body().allergens()).containsExactly(EGG, MILK);
73	
74	        // 同键同参重放首次冻结结果，不重复加版本。
75	        ServiceResult<LineControlResults.FormulaAllerView> replay =
76	                lineService.registerFormulaAllergens(first);
77	        assertThat(replay.replayed()).isTrue();
78	        assertThat(replay.body().version()).isEqualTo(1);
79	
80	        // 修改携带 expectedVersion=1，成功变更加 1。
81	        FormulaAllergenRequest changed = Fixtures.allergens(Fixtures.requestId(), "P-A", 1,
82	                List.of(PEANUT), 1, t0 + 1000);
83	        ServiceResult<LineControlResults.FormulaAllerView> updated =
84	                lineService.registerFormulaAllergens(changed);
85	        assertThat(updated.body().version()).isEqualTo(2);
86	        assertThat(updated.body().allergens()).containsExactly(PEANUT);
87	
88	        // 陈旧 expectedVersion=1 再次提交：409 乐观冲突，版本保持 2。
89	        FormulaAllergenRequest stale = Fixtures.allergens(Fixtures.requestId(), "P-A", 1,
90	                List.of(EGG), 1, t0 + 2000);
91	        assertThatThrownBy(() -> lineService.registerFormulaAllergens(stale))
92	                .isInstanceOf(ApiException.class)
93	                .satisfies(ex -> assertThat(((ApiException) ex).getCode())
94	                        .isEqualTo("OPTIMISTIC_VERSION_CONFLICT"));
95	        assertThat(lineService.getAllergenRegistration("P-A", 1).version()).isEqualTo(2);
96	    }
97	
98	    @Test
99	    void allergenRegistrationRejectsUnknownCatalogBlankAndDuplicateCreate() {
100	        long t0 = 1_800_000_000_000L;
101	        // 合成目录之外的过敏原：400。
102	        FormulaAllergenRequest unknown = Fixtures.allergens(Fixtures.requestId(), "P-X", 1,
103	                List.of("ALG_SHELLFISH"), 0, t0);
104	        assertThatThrownBy(() -> lineService.registerFormulaAllergens(unknown))
105	                .isInstanceOf(ApiException.class)
106	                .satisfies(ex -> {
107	                    ApiException api = (ApiException) ex;
108	                    assertThat(api.getStatus()).isEqualTo(HttpStatus.BAD_REQUEST);
109	                    assertThat(api.getCode()).isEqualTo("ALLERGEN_NOT_FOUND");
110	                });
111	
112	        registerAllergens(Fixtures.requestId(), "P-X", 1, List.of(MILK), 0, t0);
113	        // 已登记再以新增 expectedVersion=0：409。
114	        FormulaAllergenRequest duplicate = Fixtures.allergens(Fixtures.requestId(), "P-X", 1,
115	                List.of(MILK), 0, t0);
