1	package com.example.starter.compliance.support;
2	
3	import com.example.starter.compliance.ApiException;
4	import com.fasterxml.jackson.core.JsonProcessingException;
5	import com.fasterxml.jackson.databind.DeserializationFeature;
6	import com.fasterxml.jackson.databind.JsonNode;
7	import com.fasterxml.jackson.databind.ObjectMapper;
8	import java.io.IOException;
9	import java.io.UncheckedIOException;
10	import java.math.BigDecimal;
11	import java.util.ArrayList;
12	import java.util.List;
13	import java.util.Map;
14	import java.util.TreeMap;
15	import org.springframework.http.HttpStatus;
16	
17	/**
18	 * 快照序列化与幂等指纹工具：
19	 * 快照以 JSON 落库，保证可复算、重复查询结果稳定；
20	 * 指纹规范化 BigDecimal 标度（1.0 与 1.00 视为同参）并递归按字段名排序。
21	 */
22	public final class JsonSupport {
23	
24	    private static final ObjectMapper MAPPER = new ObjectMapper()
25	            .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
26	
27	    private JsonSupport() {
28	    }
29	
30	    public static String write(Object value) {
31	        try {
32	            return MAPPER.writeValueAsString(value);
33	        } catch (JsonProcessingException e) {
34	            throw new UncheckedIOException(e);
35	        }
36	    }
37	
38	    public static <T> T read(String json, Class<T> type) {
39	        try {
40	            return MAPPER.readValue(json, type);
41	        } catch (IOException e) {
42	            throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR, "SNAPSHOT_UNREADABLE",
43	                    "存储快照无法解析");
44	        }
45	    }
46	
47	    public static <T> T convert(Object value, Class<T> type) {
48	        return MAPPER.convertValue(value, type);
49	    }
50	
51	    /** 反序列化字符串列表（过敏原集合以 JSON 数组落库）。 */
52	    public static List<String> readStringList(String json) {
53	        try {
54	            return MAPPER.readValue(json,
55	                    MAPPER.getTypeFactory().constructCollectionType(List.class, String.class));
56	        } catch (IOException e) {
57	            throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR, "SNAPSHOT_UNREADABLE",
58	                    "存储列表无法解析");
59	        }
60	    }
61	
62	    public static JsonNode readTree(String json) {
63	        try {
64	            return MAPPER.readTree(json);
65	        } catch (IOException e) {
66	            throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR, "SNAPSHOT_UNREADABLE",
67	                    "存储快照无法解析");
68	        }
69	    }
70	
71	    /**
72	     * 反序列化幂等重放响应：存储体为首次结果（replayed=false），重放时将响应体 replayed 置为 true，
73	     * 其余字段与首次结果完全一致。
74	     */
75	    public static <T> T readReplayed(String json, Class<T> type) {
76	        JsonNode node = readTree(json);
77	        if (node.isObject() && node.has("replayed")) {
78	            ((com.fasterxml.jackson.databind.node.ObjectNode) node).put("replayed", true);
79	        }
80	        return MAPPER.convertValue(node, type);
81	    }
82	
83	    /**
84	     * 规范化业务报文：BigDecimal 去尾随零（1.00 与 1.0 视为同参），对象键递归字典序排序，
85	     * 输出稳定 JSON 字符串作为 requestId 幂等指纹输入。
86	     */
87	    public static String canonical(Object value) {
88	        Object normalized = normalize(MAPPER.convertValue(value, JsonNode.class));
89	        try {
90	            return MAPPER.writeValueAsString(normalized);
91	        } catch (JsonProcessingException e) {
92	            throw new UncheckedIOException(e);
93	        }
94	    }
95	
96	    private static Object normalize(JsonNode node) {
97	        if (node == null || node.isNull()) {
98	            return null;
99	        }
100	        if (node.isObject()) {
101	            TreeMap<String, Object> sorted = new TreeMap<>();
102	            node.fields().forEachRemaining(entry ->
103	                    sorted.put(entry.getKey(), normalize(entry.getValue())));
104	            return sorted;
105	        }
106	        if (node.isArray()) {
107	            List<Object> list = new ArrayList<>(node.size());
108	            node.forEach(child -> list.add(normalize(child)));
109	            return list;
110	        }
111	        if (node.isNumber()) {
112	            return new BigDecimal(node.asText()).stripTrailingZeros().toPlainString();
113	        }
114	        if (node.isBoolean()) {
115	            return node.booleanValue();
116	        }
117	        return node.asText();
118	    }
119	}
