@Transactional
public ServiceResult<LineControlResults.ReworkLotView> registerReworkLot(
        RegisterReworkLotRequest request) {
    return idempotency.execute(request.requestId(), request,
            LineControlResults.ReworkLotView.class, () -> {
                String lotCode = requireText(request.lotCode(), "返工料号不能为空");
                if (request.productionRecordId() == null) throw invalid("来源量产记录不能为空");
                String productCode = requireText(request.productCode(), "来源产品编码不能为空");
                requireKg(request.availableKg(), "登记可用公斤数");
                if (request.expectedVersion() == null || request.expectedVersion() != 0) {
                    throw invalid("expectedVersion 新增登记传 0（料账版本从 1 开始，不支持修改来源或过敏原）");
                }
                if (request.registeredAt() == null || request.registeredAt() < 0) throw invalid("registeredAt 精确时刻不能为空");

                ProductionRecordRow source = repository.findProductionRecordById(request.productionRecordId())
                        .orElseThrow(() -> notFound("REWORK_SOURCE_NOT_FOUND", "来源量产记录不存在：" + ...));
                FilingRow filing = repository.findFilingById(source.filingId())
                        .orElseThrow(() -> notFound("FILING_NOT_FOUND", ...));
                FormulaRow formula = repository.findFormulaById(filing.formulaId())
                        .orElseThrow(() -> notFound("FORMULA_NOT_FOUND", ...));
                if (!formula.productCode().equals(productCode)) {
                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "REWORK_SOURCE_MISMATCH",
                            "来源量产记录属于产品 " + formula.productCode() + "，不能引用别人的配方记录：" + productCode);
                }
                // 冻结来源配方版本过敏原集合：未登记则无法冻结。
                FormulaAllergenRow allergenRow = lineRepository.findFormulaAllergen(productCode, formula.version())
                        .orElseThrow(() -> new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
                                "REWORK_ALLERGEN_NOT_REGISTERED", "来源配方版本尚未登记过敏原集合，无法冻结：..."));
                if (lineRepository.findReworkLotByCode(lotCode).isPresent()) {
                    throw new ApiException(HttpStatus.CONFLICT, "REWORK_LOT_EXISTS", "返工料号已登记：" + lotCode);
                }
                if (lineRepository.findReworkLotBySource(source.id()).isPresent()) {
                    throw new ApiException(HttpStatus.CONFLICT, "REWORK_SOURCE_ALREADY_REGISTERED", "同一来源量产记录只登记一次：" + source.id());
                }
                long now = clock.nowMillis();
                long id;
                try {
                    id = lineRepository.insertReworkLot(lotCode, source.id(), productCode,
                            formula.version(), allergenRow.allergens(), request.availableKg(),
                            request.requestId(), request.registeredAt(), now);
                } catch (DuplicateKeyException e) {
                    // 并发登记：唯一约束兜底，仅一方成功。
                    throw new ApiException(HttpStatus.CONFLICT, "REWORK_LOT_EXISTS", "返工料号或来源记录已被并发登记：" + lotCode);
                }
                ReworkLotRow saved = lineRepository.findReworkLotByCode(lotCode).orElseThrow();
                return new IdempotentExecutor.Outcome<>(buildReworkLotView(saved, false), HttpStatus.OK.value());
            });
}
